<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><section class="workspace"><div class="container"><div class="page-heading"><div><p class="eyebrow">Account directory</p><h1>Customers</h1><p>Review and maintain customer contact records.</p></div><a class="btn btn-accent" href="<?= site_url('customers/new') ?>">Add customer</a></div><?php if(!$customers): ?><div class="empty-state"><h2>No customers yet</h2><p>Add the first customer to begin the directory.</p><a class="btn btn-accent" href="<?= site_url('customers/new') ?>">Add customer</a></div><?php else: ?><div class="table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th scope="col">Full name</th><th scope="col">Email</th><th scope="col">Phone</th><th scope="col">Created</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr></thead><tbody><?php foreach($customers as $customer): ?><tr><td class="fw-semibold"><?= esc($customer['full_name']) ?></td><td><a href="mailto:<?= esc($customer['email'],'attr') ?>"><?= esc($customer['email']) ?></a></td><td><?= esc($customer['phone'] ?: 'Not provided') ?></td><td><?= esc(date('M j, Y',strtotime($customer['created_at']))) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('customers/'.$customer['id'].'/edit') ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?></div></section><?= $this->endSection() ?>
